import{_ as r}from"./chunks/reports-menueband-ansichtund-abschnitt.BJvket7c.js";import{_ as a,o as i,c as s,a3 as d,j as e,a as t}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/reportverwaltung/reportverwaltung-uebersicht.png",f=JSON.parse('{"title":"Das Menüband der Reportverwaltung","description":"","frontmatter":{"title":"Das Menüband der Reportverwaltung","source_pageid":1043,"source_revision":6528},"headers":[],"relativePath":"reporting/reportverwaltung/menueband-reportverwaltung.md","filePath":"reporting/reportverwaltung/menueband-reportverwaltung.md"}'),o={name:"reporting/reportverwaltung/menueband-reportverwaltung.md"};function u(g,n,h,c,p,b){return i(),s("div",null,[...n[0]||(n[0]=[d('<h1 id="das-menuband-der-reportverwaltung" tabindex="-1">Das Menüband der Reportverwaltung <a class="header-anchor" href="#das-menuband-der-reportverwaltung" aria-label="Permalink to &quot;Das Menüband der Reportverwaltung&quot;">​</a></h1><p><a href="/bilder/reportverwaltung/reportverwaltung-uebersicht.png"><img src="'+l+'" alt="Aktuelles Menüband und Verzeichnisbaum der Reportverwaltung" loading="lazy"></a></p><p><em>Aktuelles Menüband und Verzeichnisbaum der Reportverwaltung — Oberfläche von SchILD-NRW 3.6.0.</em></p><p>Über das Menüband verwalten Sie Reportdateien, aktualisieren die Reportumgebung und wählen die Datengrundlage für eine Ausgabe.</p><p>Das Menüband enthält <strong>Neu</strong>, <strong>Bearbeiten</strong>, <strong>Ausschneiden</strong>, <strong>Einfügen</strong>, <strong>Verzeichnisbaum</strong>, <strong>Druckerliste</strong>, <strong>Standardformulare</strong> und <strong>Datenquellen</strong>. Die Erläuterungen folgen diesen Beschriftungen.</p><p>Für die Anzeige von RTF-Dateien verwendet SchILD das unter Windows zugeordnete Standardprogramm.</p><h2 id="reportbearbeitung" tabindex="-1">Reportbearbeitung <a class="header-anchor" href="#reportbearbeitung" aria-label="Permalink to &quot;Reportbearbeitung&quot;">​</a></h2><p>Der Bereich <strong>Reportbearbeitung</strong> bietet die aus Windows bekannten Funktionen zum Verwalten von Dateien im Reportexplorer.</p><table tabindex="0"><thead><tr><th>Funktion</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Neu</strong></td><td>Erstellt einen neuen, leeren Report im gewählten Ordner.</td></tr><tr><td><strong>Bearbeiten</strong></td><td>Öffnet den ausgewählten Report im Reporteditor.</td></tr><tr><td><strong>Ausschneiden</strong></td><td>Merkt den ausgewählten Report zum Verschieben vor. Wird er in einem anderen Ordner eingefügt, wird das Original am bisherigen Ort entfernt.</td></tr><tr><td><strong>Einfügen</strong></td><td>Fügt einen zum Kopieren oder Ausschneiden vorgemerkten Report im aktuellen Ordner ein.</td></tr></tbody></table><h2 id="allgemeine-reportfunktionen" tabindex="-1">Allgemeine Reportfunktionen <a class="header-anchor" href="#allgemeine-reportfunktionen" aria-label="Permalink to &quot;Allgemeine Reportfunktionen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Funktion</th><th>Wann wird sie benötigt?</th></tr></thead><tbody><tr><td><strong>Verzeichnisbaum</strong></td><td>Wenn Sie parallel im Windows-Explorer Ordner geändert oder neue Reports, etwa Zeugnisformulare, abgelegt haben. Die Ordnerstruktur im Reportexplorer wird neu eingelesen.</td></tr><tr><td><strong>Druckerliste</strong></td><td>Liest die von Windows bereitgestellten Drucker neu ein, damit SchILD-NRW 3 sie verwenden kann.</td></tr><tr><td><strong>Standardformulare</strong></td><td>Zeigt die Reports an, die als Standard für Stammblatt und Schulbescheinigung festgelegt sind.</td></tr><tr><td><strong>Datenquellen</strong></td><td>Zeigt die verfügbaren Datenquellen, ihre Struktur und die darin bereitgestellten Datenbankfelder an.</td></tr></tbody></table><p>Die Standardformulare legen Sie mit einem Rechtsklick auf den jeweiligen Report fest. Anschließend lassen sich Stammblatt und Schulbescheinigung unter <strong>Individualdaten I</strong> im Bereich <strong>Drucken</strong> mit einem Klick erzeugen. Die Anleitung <a href="/reporting/serienbriefe/direkter-zugriff-auf-das-schuelerstammblatt-und-die-schulbescheinigung.html">Direkter Zugriff auf das Schülerstammblatt und die Schulbescheinigung</a> erläutert diesen Zugang.</p><h2 id="ansicht-und-ausgewahltes-schuljahr" tabindex="-1">Ansicht und ausgewähltes Schuljahr <a class="header-anchor" href="#ansicht-und-ausgewahltes-schuljahr" aria-label="Permalink to &quot;Ansicht und ausgewähltes Schuljahr&quot;">​</a></h2><p><a href="/bilder/reportverwaltung/reports-menueband-ansichtund-abschnitt.png"><img src="'+r+'" alt="Die Bereiche Ansicht und Ausgewähltes Schuljahr." loading="lazy"></a></p><p><em>Die Bereiche Ansicht und Ausgewähltes Schuljahr.</em></p><p>Im Bereich <strong>Ansicht</strong> wählen Sie, welche Dateiinformationen angezeigt werden.</p><table tabindex="0"><thead><tr><th>Ansicht</th><th>Angezeigte Angaben</th></tr></thead><tbody><tr><td><strong>Details</strong></td><td>Dateiname, Dateigröße in Byte sowie Datum und Uhrzeit der letzten Änderung. Der Zeitstempel hilft, den Stand einer Reportdatei zu erkennen; diese Ansicht ist deshalb zu empfehlen.</td></tr><tr><td><strong>Liste</strong></td><td>Nur der Dateiname.</td></tr></tbody></table><p>Unter <strong>Schuljahr/Abschnitt</strong> wählen Sie den Lernabschnitt, dessen Daten für den anschließend erzeugten Report verwendet werden.</p>',18),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),t("Beispiel: Abgangszeugnis nach dem Abschnittswechsel")]),e("p",null,"Nach dem Wechsel in den nächsten Abschnitt stellt sich heraus, dass eine Schülerin oder ein Schüler die Schule verlässt und im aktuellen Abschnitt nicht mehr beschult wird. Für das Abgangszeugnis können Sie den vorherigen Abschnitt als Datengrundlage auswählen.")],-1),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),t("Wichtig – Wieder auf den aktuellen Abschnitt zurückstellen")]),e("p",null,"Stellen Sie nach der Ausgabe wieder den aktuellen Abschnitt ein. Andernfalls können weitere Reportausgaben mit Daten des falschen Abschnitts erzeugt werden.")],-1),e("p",null,[t("Die Arbeitsschritte zeigt "),e("a",{href:"/reporting/reportverwaltung/daten-aus-zurueckliegenden-abschnitten-drucken.html"},"Daten aus zurückliegenden Abschnitten drucken"),t(".")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Men%C3%BCband_(Reportverwaltung)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),t(" · Quellrevision 6528.")],-1)])])}const k=a(o,[["render",u]]);export{f as __pageData,k as default};
